// Integer Multiplier Variable-Latency Implementation
//=========================================================================

`ifndef LAB1_IMUL_INT_MUL_ALT_V
`define LAB1_IMUL_INT_MUL_ALT_V

`include "vc/arithmetic.v"
`include "vc/muxes.v"
`include "vc/trace.v"

module lab1_imul_IntMulTrailingZero
(
  input  logic [31:0] in,
  output logic [4:0]  trailing_zeros
);

  always_comb begin
    trailing_zeros = 5'd0;
    for ( int i = 0; i < 32; i++ ) begin
      if ( in[i] ) begin
        trailing_zeros = i[4:0];
        break;
      end
    end
  end

endmodule

//=========================================================================
// Datapath
//=========================================================================

module lab1_imul_IntMulAltDpath
(
  input  logic        clk,
  input  logic        reset,

  input  logic [63:0] istream_msg,
  output logic [31:0] ostream_msg,

  // Control signals from the control unit

  input  logic        a_mux_sel,
  input  logic        b_mux_sel,
  input  logic        result_mux_sel,
  input  logic        result_en,

  // Status signals to the control unit

  output logic        b_is_zero,
  output logic [5:0]  shift_amount,

  // Internal values exported for line tracing

  output logic [31:0] a_reg_out,
  output logic [31:0] b_reg_out,
  output logic [31:0] result_reg_out
);

  //-----------------------------------------------------------------------
  // Determine how far to skip
  //-----------------------------------------------------------------------

  logic [4:0] trailing_zeros;

  lab1_imul_IntMulTrailingZero trailing_zero
  (
    .in             (b_reg_out),
    .trailing_zeros (trailing_zeros)
  );

  assign b_is_zero = (b_reg_out == 32'b0);

  // Add 1 to the number of trailing zeros

  assign shift_amount = {1'b0,trailing_zeros} + 6'd1;

  //-----------------------------------------------------------------------
  // A operand path
  //-----------------------------------------------------------------------

  logic [31:0] a_mux_out;
  logic [31:0] a_skip_out;
  logic [31:0] a_shift_out;

  vc_Mux2#(32) a_mux
  (
    .in0 (istream_msg[63:32]),
    .in1 (a_shift_out),
    .sel (a_mux_sel),
    .out (a_mux_out)
  );

  always_ff @( posedge clk ) begin
    if ( reset ) a_reg_out <= 32'b0;
    else         a_reg_out <= a_mux_out;
  end

  // First skip the trailing zeros. This value feeds the result adder.

  assign a_skip_out = a_reg_out << trailing_zeros;

  // Then shift past the set bit that was just added. This value feeds
  // back into the A register for the next iteration.

  assign a_shift_out = a_skip_out << 1;

  //-----------------------------------------------------------------------
  // B operand path
  //-----------------------------------------------------------------------

  logic [31:0] b_mux_out;
  logic [31:0] b_shift_out;

  vc_Mux2#(32) b_mux
  (
    .in0 (istream_msg[31:0]),
    .in1 (b_shift_out),
    .sel (b_mux_sel),
    .out (b_mux_out)
  );

  always_ff @( posedge clk ) begin
    if ( reset ) b_reg_out <= 32'b0;
    else         b_reg_out <= b_mux_out;
  end

  // Shift B past the trailing zeros and the set bit that was just added

  assign b_shift_out = b_reg_out >> shift_amount;

  //-----------------------------------------------------------------------
  // Result path
  //-----------------------------------------------------------------------

  logic [31:0] add_out;
  logic [31:0] result_mux_out;

  assign add_out = a_skip_out + result_reg_out;

  vc_Mux2#(32) result_mux
  (
    .in0 (32'b0),
    .in1 (add_out),
    .sel (result_mux_sel),
    .out (result_mux_out)
  );

  always_ff @( posedge clk ) begin
    if      ( reset )     result_reg_out <= 32'b0;
    else if ( result_en ) result_reg_out <= result_mux_out;
  end

  assign ostream_msg = result_reg_out;

endmodule

//=========================================================================
// Control Unit
//=========================================================================

module lab1_imul_IntMulAltCtrl
(
  input  logic       clk,
  input  logic       reset,

  input  logic       istream_val,
  output logic       istream_rdy,

  output logic       ostream_val,
  input  logic       ostream_rdy,

  // Status signals from the datapath

  input  logic       b_is_zero,
  input  logic [5:0] shift_amount,

  // Control signals to the datapath

  output logic       a_mux_sel,
  output logic       b_mux_sel,
  output logic       result_mux_sel,
  output logic       result_en,

  // Internal values exported for line tracing

  output logic [1:0] status,
  output logic [5:0] counter
);

  localparam logic [1:0] IDLE = 2'd0;
  localparam logic [1:0] CALC = 2'd1;
  localparam logic [1:0] DONE = 2'd2;

  logic [1:0] status_next;
  logic [5:0] counter_next;

  //-----------------------------------------------------------------------
  // State elements
  //-----------------------------------------------------------------------

  always_ff @( posedge clk ) begin
    if ( reset ) begin
      status  <= IDLE;
      counter <= 6'd0;
    end
    else begin
      status  <= status_next;
      counter <= counter_next;
    end
  end

  //-----------------------------------------------------------------------
  // State transitions
  //-----------------------------------------------------------------------

  always_comb begin
    status_next = status;

    case ( status )
      IDLE: if ( istream_val ) status_next = CALC;
      CALC: begin
        if ( b_is_zero || (counter == 6'd32) ) status_next = DONE;
      end
      DONE: if ( ostream_rdy ) status_next = IDLE;
      default:                 status_next = IDLE;
    endcase
  end

  //-----------------------------------------------------------------------
  // State outputs
  //-----------------------------------------------------------------------

  always_comb begin
    istream_rdy    = 1'b0;
    ostream_val    = 1'b0;
    a_mux_sel      = 1'b0;
    b_mux_sel      = 1'b0;
    result_mux_sel = 1'b0;
    result_en      = 1'b0;
    counter_next   = counter;

    case ( status )
      IDLE: begin
        istream_rdy  = 1'b1;
        result_en    = 1'b1;
        counter_next = 6'd0;
      end

      CALC: begin
        a_mux_sel      = 1'b1;
        b_mux_sel      = 1'b1;
        result_mux_sel = 1'b1;

        if ( !b_is_zero && (counter < 6'd32) ) begin
          result_en    = 1'b1;
          counter_next = counter + shift_amount;
        end
      end

      DONE: begin
        ostream_val = 1'b1;
      end

      default: begin
        counter_next = 6'd0;
      end
    endcase
  end

endmodule

